    const width = 600;
    const height = 600;

    // Process data
    data.forEach(d => {
        d.marketCap = d.marketCap ? +d.marketCap : null;
    });

    const sectors = Array.from(new Set(data.map(d => d.sector)));
    const color = d3.scaleOrdinal().domain(sectors).range(d3.schemeCategory10);

    const sizeScale = d3.scaleSqrt()
        .domain([0, d3.max(data, d => d.marketCap || 0)])
        .range([10, 60]);

    const nodes = data.map(d => ({
        ...d,
        radius: d.marketCap ? sizeScale(d.marketCap) : 20
    }));

    const simulation = d3.forceSimulation(nodes)
        .force("x", d3.forceX(width / 2).strength(0.05))
        .force("y", d3.forceY(height / 2).strength(0.05))
        .force("collide", d3.forceCollide(d => d.radius + 2))
        .force("sectorX", d3.forceX(d => {
            const idx = sectors.indexOf(d.sector);
            return (idx % 3 + 1) * (width / 4);
        }).strength(0.1))
        .force("sectorY", d3.forceY(d => {
            const idx = sectors.indexOf(d.sector);
            return (Math.floor(idx / 3) + 1) * (height / 4);
        }).strength(0.1));

